var n=`1354-bolon-de-verde`;var i=`world-1354`;var t=`EC`;var a=`south-america`;var s=4;var r=54;var d={en:`Bolón de Verde`,ua:`Болон де верде`};var u={en:`Bolón de Verde is a dish from Ecuador featuring plantain, queso fresco, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Болон де верде, страва кухні країни Еквадор з такими основними складниками: плантан, кесо фреско, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`plantain`,850,`g`],[`canola-oil`,100,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 11 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 11 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:11,i:[[`queso-fresco`,230,`g`],[`garlic`,3,`clove`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 13 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 13 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:13,i:[[`canola-oil`,100,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-black-pepper`,4,`g`]]}];var h={slug:n,id:i,country:`EC`,region:a,servings:4,minutes:54,title:d,text:u,steps:l};export{t as country,h as default,i as id,r as minutes,a as region,s as servings,n as slug,l as steps,u as text,d as title};